<script setup lang="ts">
import {computed} from 'vue';
import FlowWizardReview from './FlowWizardReview.vue';
import VariableReview from './VariableReview.vue';
import {scheduleContextLabel} from '../lib/schedule-editor';
import {AlertCircle,ArrowRight,Copy,FileDiff,ShieldCheck} from 'lucide-vue-next';
type Item=Record<string,any>;
const props=defineProps<{approval:Item;tenants:Item[]}>();
const action=computed(()=>props.approval.payload?.action??{});
const revision=computed(()=>props.approval.payload?.revision??{});
const info=computed(()=>{const data=revision.value.info?.data;const payload=data?.payload??data??{};return payload.body??payload;});
const tenant=computed(()=>props.tenants.find(t=>String(t.id)===String(revision.value.tenant_id))?.name??revision.value.tenant_id);
const deskId=computed(()=>action.value.desk??info.value.deskId??info.value.desk_id??(typeof info.value._state==='object'?info.value._state?.deskId:null));
const loadPlan=computed(()=>revision.value.load_plan??null);
const scheduleEdit=computed(()=>revision.value.schedule_edit??null);
const scheduleAction=computed(()=>String(action.value.resource??'').startsWith('schedule:'));
const scheduleTiming=computed(()=>props.approval.schedule_timing??null);
const cloned=computed(()=>['clone_app','clone_flow'].includes(action.value.action));
const flowClone=computed(()=>action.value.action==='clone_flow'?revision.value.flow_clone:null);
const deleted=computed(()=>action.value.action==='delete_draft');
const appDeletion=computed(()=>deleted.value?revision.value.app_deletion:null);
const flowDeletion=computed(()=>deleted.value?revision.value.flow_deletion:null);
const publish=computed(()=>String(action.value.action??'').startsWith('publish'));
const publication=computed(()=>revision.value.publication??null);
const flowPublication=computed(()=>publication.value?.kind==='flow'?publication.value:null);
const credential=computed(()=>revision.value.credential??null);
const etl=computed(()=>revision.value.etl??null);
const flowWizard=computed(()=>revision.value.flow_wizard??null);
const desk=computed(()=>revision.value.desk??null);
const variableEdit=computed(()=>['create_variable','update_variable'].includes(action.value.action)?revision.value.variable:null);
const appDetails=computed(()=>action.value.action==='update_app_details'?revision.value.app_details:null);
const tablePresentation=computed(()=>action.value.action==='update_table_presentation'?revision.value.table:null);
function tableChangeValue(field:string,value:unknown){if(field==='Formato')return ({N0:'Número inteiro',N2:'Número com 2 casas decimais',MOEDA:'Valor monetário',PCT1:'Percentual com 1 casa decimal'} as Record<string,string>)[String(value)]??(value?'Formato personalizado do BI':'Padrão do BI');return value===null||value===''?'Sem valor':String(value);}
const textDiff=computed(()=>{const data=revision.value.changes?.data??{};return data.workingVsServer?.unified??data.workingVsState?.unified??'';});
const changedLines=computed(()=>String(textDiff.value).split('\n').filter(line=>/^[+-](?![+-])/.test(line)));
const excerpt=computed(()=>changedLines.value.slice(0,40).map(line=>line.length>1000?line.slice(0,1000)+'…':line).join('\n').slice(0,12000));
</script>
<template><div class="approval-review" :class="{'flow-publication-review':!!flowPublication}"><dl><div><dt>Tenant</dt><dd>{{tenant}}</dd></div><div><dt>Recurso</dt><dd>{{variableEdit?.key||appDetails?.name||tablePresentation?.name||credential?.name||desk?.name||scheduleEdit?.name||info.nome||info.name||action.resource}} <small v-if="action.resource&&(info.nome||info.name||desk||credential||tablePresentation||appDetails||scheduleEdit)">{{action.resource}}</small></dd></div><div><dt>Destino</dt><dd>{{variableEdit?'Variáveis do tenant':appDetails?(appDetails.state==='published'?'Aplicação publicada · Mesa #'+appDetails.desk_id:'Aplicação atual · Minha Mesa'):scheduleEdit?'Agente · '+scheduleEdit.agent.name:tablePresentation?'Tabela atual · '+tablePresentation.column_count+' campos':desk?desk.label:credential?'Agente · '+credential.agent.name:publication?publication.destination.name:cloned?'Minha Mesa · nova cópia':scheduleAction?'Agente #'+(revision.schedule?.tokenId??info.tokenId??'a conferir'):(deskId?'Mesa #'+deskId:'Minha Mesa · rascunho')}}<small v-if="publication">{{publication.destination.resource}}</small></dd></div><div v-if="cloned"><dt>Nome da cópia</dt><dd>{{action.name}}</dd></div><div v-if="info.cloned_from"><dt>Origem da cópia</dt><dd>Aplicação #{{info.cloned_from}}</dd></div></dl><FlowWizardReview v-if="flowWizard" :value="flowWizard"/><VariableReview v-else-if="variableEdit" :value="variableEdit" :impact="revision.impact"/><template v-else-if="etl"><div class="review-changes"><strong>Etapa a executar</strong><p>{{etl.node}} · {{etl.kind}} · Agente #{{etl.agent_id}}</p><p>{{etl.writes_datawarehouse?'Inclui gravação no Data Warehouse. Confira a tabela de destino.':'Não há etapa de inserção no DW nesta cadeia. A fonte será consultada pelo agente.'}}</p><p v-for="step in etl.steps" :key="step.id">{{step.description||step.id}} · {{step.kind}}<span v-if="step.table_id"> · Tabela #{{step.table_id}}</span></p><details v-if="etl.steps.some((step:Item)=>step.sql)"><summary>Consultas desta etapa</summary><pre v-for="step in etl.steps.filter((step:Item)=>step.sql)" :key="step.id">{{step.sql}}</pre></details></div><p class="review-impact">{{etl.impact}}</p></template><template v-else-if="scheduleEdit"><div class="schedule-review-comparison"><article v-if="scheduleEdit.previous"><h3>Atual</h3><p><strong>{{scheduleEdit.previous.nome}}</strong> · {{scheduleEdit.previous.ativo?'Ativa':'Inativa'}}</p><p>{{scheduleEdit.previous.agent_name}}</p><p>{{scheduleTiming?.previous_frequency??'Confira os horários na revisão técnica'}}</p><ol><li v-for="(flow,index) in scheduleEdit.previous.sources" :key="index">{{flow.name}}<small>{{scheduleContextLabel(flow.context)}}</small></li></ol><p>Avisos: {{scheduleEdit.previous.notifications.on_error?'erros':''}}{{scheduleEdit.previous.notifications.on_error&&scheduleEdit.previous.notifications.on_success?' e ':''}}{{scheduleEdit.previous.notifications.on_success?'conclusões':''}}{{!scheduleEdit.previous.notifications.on_error&&!scheduleEdit.previous.notifications.on_success?'desativados':''}}</p><p v-if="scheduleEdit.previous.notifications.emails?.length">{{scheduleEdit.previous.notifications.emails.join(', ')}}</p><p>Fila: {{scheduleEdit.previous.parallel_lane?'paralela':'padrão'}}</p></article><article><h3>{{scheduleEdit.creating?'Nova agenda':'Proposto'}}</h3><p><strong>{{scheduleEdit.name}}</strong> · {{scheduleEdit.active?'Ativa':'Inativa'}}</p><p>{{scheduleEdit.agent.name}}</p><p>{{scheduleTiming?.frequency??'Confira os horários na revisão técnica'}}</p><ol><li v-for="(flow,index) in scheduleEdit.sources" :key="index">{{flow.name}}<small>{{scheduleContextLabel(flow.context)}}</small></li></ol><p>Avisos: {{scheduleEdit.notifications.on_error?'erros':''}}{{scheduleEdit.notifications.on_error&&scheduleEdit.notifications.on_success?' e ':''}}{{scheduleEdit.notifications.on_success?'conclusões':''}}{{!scheduleEdit.notifications.on_error&&!scheduleEdit.notifications.on_success?'desativados':''}}</p><p v-if="scheduleEdit.notifications.emails?.length">{{scheduleEdit.notifications.emails.join(', ')}}</p><p>Fila: {{scheduleEdit.parallel_lane?'paralela':'padrão'}}</p></article></div><p class="review-impact">{{revision.impact}}</p></template><template v-else-if="tablePresentation||appDetails"><div class="table-review-changes"><strong>{{appDetails?'Nome e descrição da aplicação':'Alterações na apresentação da tabela'}}</strong><article v-for="(change,index) in revision.changes" :key="index"><header>{{change.target}} <span>· {{change.field}}</span></header><div><small>Atual</small><p>{{tableChangeValue(change.field,change.before)}}</p></div><div><small>Proposto</small><p>{{tableChangeValue(change.field,change.after)}}</p></div></article></div><p class="review-impact">{{revision.impact}}</p></template><template v-else-if="desk"><div class="review-changes"><strong>{{desk.previous?'Alterações na mesa':'Nova mesa'}}</strong><p v-if="desk.previous">Nome atual: {{desk.previous.name}}<br>Descrição atual: {{desk.previous.description||'Sem descrição'}}</p><p>Nome proposto: {{desk.name}}<br>Descrição proposta: {{desk.description||'Sem descrição'}}</p></div><p class="review-impact">{{revision.impact}}</p></template><template v-else-if="credential"><dl><div><dt>Tipo de banco</dt><dd>{{credential.type}}</dd></div><div v-for="(value,key) in credential.configuration" :key="key"><dt>{{key}}</dt><dd>{{value}}</dd></div></dl><p v-for="field in credential.protected_fields" :key="field" class="credential-protected">{{field}}</p><p class="review-impact">{{credential.impact}}</p></template><div v-else-if="flowClone" class="review-impact"><Copy :size="18"/><div><p><strong>{{flowClone.node_count}} {{flowClone.node_count===1?'etapa':'etapas'}}</strong> e {{flowClone.source_table_refs.length}} {{flowClone.source_table_refs.length===1?'destino':'destinos'}} serão duplicados. O novo projeto ficará vinculado ao ETL da cópia.</p><p>{{flowClone.impact}}</p></div></div><div v-else-if="cloned" class="review-impact"><Copy :size="18"/><p>Será criada uma nova aplicação na sua mesa, com um projeto próprio. A aplicação original permanece como está. A cópia continua usando as fontes de dados existentes.</p></div><div v-else-if="flowDeletion" class="review-impact"><AlertCircle :size="18"/><div><p><strong>Excluir este ETL e {{flowDeletion.tables.length}} {{flowDeletion.tables.length===1?'tabela de destino':'tabelas de destino'}}</strong></p><p>{{flowDeletion.impact}}</p><div v-for="table in flowDeletion.tables" :key="table.resource" class="flow-publication-table"><strong>{{table.name}}</strong><p>{{table.resource}} · {{table.column_count}} {{table.column_count===1?'campo':'campos'}}</p></div></div></div><div v-else-if="appDeletion" class="review-impact"><AlertCircle :size="18"/><div><p><strong>Excluir esta aplicação de teste</strong></p><p v-if="appDeletion.dashboard_count">{{appDeletion.dashboard_count}} {{appDeletion.dashboard_count===1?'dashboard será removido':'dashboards serão removidos'}} com esta aplicação.</p><p v-else>Esta aplicação não contém dashboards nesta revisão.</p><p>{{appDeletion.impact}}</p><p v-if="appDeletion.preserved_table_refs.length">{{appDeletion.preserved_table_refs.length}} {{appDeletion.preserved_table_refs.length===1?'tabela vinculada será preservada':'tabelas vinculadas serão preservadas'}}.</p></div></div><div v-else-if="deleted" class="review-impact"><AlertCircle :size="18"/><p>Este rascunho será excluído. O sistema confirma que ele foi criado por este projeto e preserva uma revisão local antes da remoção. A aplicação original e as fontes não são removidas.</p></div><div v-else-if="publish" class="review-impact" :class="{'flow-publication-impact':!!flowPublication}"><AlertCircle :size="18"/><div><template v-if="flowPublication"><p v-if="flowPublication.mode==='replace'">Será substituído o ETL <strong>“{{flowPublication.target.name}}”</strong> nesta mesa.</p><p v-else>O ETL <strong>“{{flowPublication.source.name}}”</strong> será publicado como uma nova entrada nesta mesa.</p><p>{{flowPublication.impact}}</p><div v-for="table in flowPublication.tables" :key="table.source_ref" class="flow-publication-table"><strong>{{table.name}}</strong><p>{{table.column_count}} {{table.column_count===1?'campo':'campos'}} · {{table.source_ref}}{{table.source_ref!==table.target_ref?' → '+table.target_ref:''}}</p><template v-if="table.schema_changes"><p v-if="table.schema_changes.removed.length"><strong>Campos removidos:</strong> {{table.schema_changes.removed.join(', ')}}</p><p v-if="table.schema_changes.changed_types.length"><strong>Tipos alterados:</strong> <span v-for="(field,index) in table.schema_changes.changed_types" :key="field.name">{{index?', ':''}}{{field.name}} ({{field.previous}} → {{field.next}})</span></p><p v-if="table.schema_changes.added.length"><strong>Campos adicionados:</strong> {{table.schema_changes.added.join(', ')}}</p><p v-if="table.schema_changes.storage_changed"><strong>O modelo de armazenamento foi alterado.</strong> Confira a necessidade de uma nova carga.</p><p v-if="!table.schema_changes.removed.length&&!table.schema_changes.changed_types.length&&!table.schema_changes.added.length&&!table.schema_changes.storage_changed">Os nomes e tipos dos campos conferidos permanecem equivalentes.</p></template></div><p><strong>{{flowPublication.copy_data?'Solicita copiar os dados de teste para a tabela original.':'Não solicita copiar os dados de teste.'}}</strong></p><p>{{flowPublication.data_impact}}</p></template><template v-else><p v-if="publication?.mode==='replace'">A aplicação <strong>“{{publication.target.name}}”</strong> nesta mesa receberá o conteúdo deste rascunho. A cópia de trabalho será incorporada à versão publicada.</p><p v-else-if="publication?.mode==='new'">A aplicação <strong>“{{publication.source.name}}”</strong> ficará disponível como uma nova entrada nesta mesa. As versões existentes serão preservadas.</p><p v-else>Prepare uma nova revisão para conferir o destino e o efeito desta publicação.</p><p v-if="publication?.source?.content_sha256">Após publicar, o conteúdo será comparado à revisão: dashboards, gráficos, expressões, filtros e fontes. A atualização dos dados é conferida separadamente.</p></template><p>A versão publicada será compartilhada com os usuários autorizados da mesa.</p></div></div><div v-if="revision.schedule&&!scheduleEdit" class="review-changes"><strong>Agenda desta revisão</strong><p>{{revision.schedule.nome}} · {{revision.schedule.ativo?'Ativa':'Inativa'}} · {{revision.schedule.timezone}}</p><p v-for="flow in revision.schedule.flows" :key="flow.flow_etl_id">Fonte #{{flow.flow_etl_id}} · {{flow.context}}</p><p v-for="(trigger,index) in revision.schedule.triggers" :key="index">{{scheduleTiming?.triggers?.[index]??'Frequência a conferir na revisão técnica'}}</p></div><div v-if="excerpt" class="review-changes"><strong><FileDiff :size="16"/>Alterações propostas</strong><pre>{{excerpt}}</pre><p v-if="changedLines.length>40">Mostrando parte das alterações. Consulte a revisão técnica completa abaixo.</p></div><p v-else-if="action.action==='run_schedule'" class="review-impact">Esta autorização permite iniciar uma carga real de dados. A conclusão exige o resultado confirmado de todas as fontes no BI.</p><p v-else-if="action.action==='resume_schedule'" class="review-impact">A agenda passará a executar automaticamente. Confira fontes, frequência e agente na revisão técnica.</p><p v-else-if="!etl&&!desk&&!credential&&!tablePresentation&&!appDetails&&!variableEdit&&!scheduleEdit&&!deleted&&!publish&&!cloned" class="review-impact">Confira o recurso e o destino. Esta autorização vale somente para a revisão apresentada.</p><details><summary>Ver revisão técnica completa</summary><pre>{{JSON.stringify(approval.payload,null,2)}}</pre></details><section v-if="loadPlan" class="load-review"><h3>Fontes que serão atualizadas</h3><ol><li v-for="(binding,index) in loadPlan.bindings" :key="index">{{binding.name}} · {{scheduleContextLabel(binding.context)}}</li></ol><p>Os dados serão gravados no BI. Sincronização de exclusões também remove do destino os registros ausentes na origem. Esta autorização executa uma vez e preserva horários, ativação e publicação.</p></section></div></template>
<style scoped>.approval-review{background:#fff;border:1px solid #e4e8f0;border-radius:10px;padding:18px;margin:18px 0}.approval-review dl{display:grid;grid-template-columns:1fr 1.4fr 1fr;gap:18px;margin:0 0 16px}.approval-review dt{font-size:11px;color:#68758a;margin-bottom:5px}.approval-review dd{font-size:13px;font-weight:600;margin:0;color:#20314c}.approval-review small{display:block;font-weight:400;color:#758198;margin-top:4px}.review-impact{display:flex;gap:9px;font-size:12px;line-height:1.7;color:#6c5633;background:#fff8eb;border-radius:7px;padding:12px}.review-impact p{margin:0}.review-impact svg{flex-shrink:0;margin-top:3px}.review-changes>strong{display:flex;align-items:center;gap:8px;font-size:12px;color:#314a71;margin:14px 0}.approval-review pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:240px;overflow:auto;font-size:11px;background:#f4f7fb;color:#34425a;padding:13px;border-radius:6px}.approval-review details{margin-top:16px}.approval-review summary{cursor:pointer;color:#65758b;font-size:12px}.approval-review details pre{max-height:320px}.review-changes>p{font-size:12px;color:#8b6418}.table-review-changes>strong{display:block;font-size:12px;color:#314a71;margin:16px 0}.table-review-changes article{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:10px 18px;padding:14px 0;border-top:1px solid #e6ecf5}.table-review-changes header{grid-column:1/-1;font-size:12px;font-weight:600;color:#3e577a;overflow-wrap:anywhere}.table-review-changes header span{font-weight:400;color:#8190a5}.table-review-changes small{font-size:10px}.table-review-changes p{font-size:12px;white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.7;margin:5px 0;color:#405976}.table-review-changes article>div:last-child{border-left:2px solid #d5e6ff;padding-left:12px}.schedule-review-comparison{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(220px,100%),1fr));gap:16px}.schedule-review-comparison article{min-width:0;background:#f5f8fd;border-radius:8px;padding:14px}.schedule-review-comparison h3{font-size:12px;margin:0 0 12px;color:#314a71}.schedule-review-comparison p,.schedule-review-comparison li{font-size:12px;line-height:1.8;overflow-wrap:anywhere;color:#405976}.schedule-review-comparison ol{padding-left:18px}.schedule-review-comparison small{margin-top:0;font-size:10px}@media(max-width:700px){.approval-review dl{grid-template-columns:1fr}}.flow-publication-table{margin:12px 0;padding:12px;border:1px solid #e7d7bb;border-radius:7px;background:#fff;overflow-wrap:anywhere}.flow-publication-table p{margin:5px 0;line-height:1.7}.flow-publication-impact p{color:#674a27;line-height:1.75}.flow-publication-table p{color:#52647e}.flow-publication-table>strong{color:#344b69}@media(max-width:650px){.flow-publication-review{padding:12px}.flow-publication-impact{display:block;padding:12px}.flow-publication-impact>svg{margin-bottom:8px}.flow-publication-table{padding:10px}}@media(max-width:600px){.table-review-changes article{grid-template-columns:minmax(0,1fr);gap:8px}.table-review-changes article>div:last-child{margin-top:2px}}</style>
<style scoped>.load-review{margin:18px 0;padding:15px;border:1px solid #dae6f6;border-radius:8px;background:#f7faff}.load-review h3{font-size:12px;color:#35557f;margin:0 0 10px}.load-review li,.load-review p{font-size:12px;line-height:1.8;color:#657f9f}.load-review ol{padding-left:20px}.load-review p{margin-bottom:0}.flow-publication-table{margin:12px 0;padding:12px;border:1px solid #e7d7bb;border-radius:7px;background:#fff;overflow-wrap:anywhere}.flow-publication-table p{margin:5px 0;line-height:1.7}.flow-publication-impact p{color:#674a27;line-height:1.75}.flow-publication-table p{color:#52647e}.flow-publication-table>strong{color:#344b69}@media(max-width:650px){.flow-publication-review{padding:12px}.flow-publication-impact{display:block;padding:12px}.flow-publication-impact>svg{margin-bottom:8px}.flow-publication-table{padding:10px}}</style>
